#!/usr/bin/env bash
set -Eeuo pipefail
panel="$(realpath -e -- "${1:-/var/www/pterodactyl}")"
site=/etc/nginx/sites-available/baba-panel.conf
[[ -f "$site" ]] || exit 0
# Only adjust the site generated by this installer and only for its panel root.
grep -Fq "root $panel/public;" "$site" || exit 0
grep -Eq '^[[:space:]]*add_header[[:space:]]+X-Frame-Options[[:space:]]+DENY;' "$site" || exit 0
command -v nginx >/dev/null
backup="$(mktemp -d /var/backups/baba-preview-nginx.XXXXXXXX)"
chmod 700 "$backup"
cp -p "$site" "$backup/baba-panel.conf"
sed -i -E '/^[[:space:]]*add_header[[:space:]]+X-Frame-Options[[:space:]]+DENY;/d' "$site"
if ! nginx -t || ! systemctl reload nginx; then
  cp -p "$backup/baba-panel.conf" "$site"
  nginx -t && systemctl reload nginx
  echo 'NGINX preview change failed; original configuration restored.' >&2
  exit 1
fi
printf 'Theme preview header conflict repaired. NGINX backup: %s\n' "$backup"
